handle(request) { const principal=authenticate();
 if(principal!==request.ownerId) throw Forbidden();
 const begun=transaction(()=>beginAttempt(principal,request.requestKey,hash(request.parameters)));
 // beginAttempt keys receipts by (ownerId, requestKey): conflict on a different hash; complete -> return it;
 // running before its deadline -> {status:"running"}; otherwise issue the next attempt token,
 // keeping the cutoff stored when the receipt was first accepted.
 if(begun.action!=="render") return begun.receipt;
 const input=readSnapshotAt(request.parameters,begun.cutoff);
 const bytes=renderWithLimits(input); const artifactHash=hash(bytes);
 artifactStore.putImmutable(artifactHash,bytes);
 return transaction(()=>completeIfRunning(principal,request.requestKey,begun.attempt,artifactHash));
 // completeIfRunning: first verified completion wins; later ones return the committed receipt unchanged.
}
